12	// V2: A single content block (link, section, etc.) on a site. Typed by block_type and block_group, sortable, with a JSON settings bag.
13	class Block extends BaseModel
14	{
15	    use HasUuids;
16	
17	    /**
18	     * @var false|mixed
19	     */
20	    protected $table = 'site.blocks';
21	
22	    public $incrementing = false;
23	
24	    protected $keyType = 'string';
25	
26	    protected $fillable = [
27	        'professional_id',
28	        'site_id',
29	        'block_type',
30	        'block_group',
31	        'title',
32	        'url',
33	        'icon_key',
34	        'sort_order',
35	        'is_active',
36	        'is_enabled',
37	        'settings',
38	    ];
39	
40	    protected $casts = [
41	        'sort_order' => 'integer',
42	        'is_active' => 'boolean',
43	        'is_enabled' => 'boolean',
44	        'settings' => 'array',
45	        'created_at' => 'datetime',
46	        'updated_at' => 'datetime',
47	    ];
48	
49	    public function professional(): BelongsTo
50	    {
51	        return $this->belongsTo(Professional::class, 'professional_id');
52	    }
53	
54	    public function site(): BelongsTo
55	    {
56	        return $this->belongsTo(Site::class, 'site_id');
57	    }
58	
59	    public function clicks(): HasMany
60	    {
61	        return $this->hasMany(LinkClick::class, LinkClick::resolveBlockForeignKeyColumn() ?? 'link_block_id');
62	    }
63	
64	    public function scopeActive($query)
65	    {
66	        return $query->where('is_active', true);
67	    }
68	
69	    public function scopeEnabled($query)
70	    {
71	        return $query->where('is_enabled', true);
72	    }
73	
74	    public function scopeVisible($query)
75	    {
76	        return $query->where('is_enabled', true)->where('is_active', true);
77	    }
