3	/**
4	 * Platform-link cap enforcement on the StoreLinkBlockRequest pipeline.
5	 *
6	 * The cap (config('sidest.platform_links_max'), default 7) is the API-side
7	 * defence-in-depth on top of the dashboard's disabled-Add-button. It must
8	 * fire on BOTH the professional self-management endpoint and the staff
9	 * management endpoint:
10	 *
11	 *   - Self path  → resolved via $request->attributes->get('professional')
12	 *                  (set by Context\LoadCurrentProfessional middleware).
13	 *   - Staff path → resolved via $request->route('professional')
14	 *                  (route-bound target professional whose site is being
15	 *                  edited; the staff member's own pro lives on the
16	 *                  attribute and is NOT the right row to count against).
17	 *
18	 * StaffStoreLinkRequest extends StoreLinkBlockRequest, so the cap logic
19	 * runs in shared code — both subclasses must resolve the right professional.
20	 */
21	
22	use App\Http\Requests\Api\Professional\Site\StoreLinkBlockRequest;
23	use App\Http\Requests\Api\Staff\ProfessionalSite\Links\StaffStoreLinkRequest;
24	use Illuminate\Routing\Route;
25	use Illuminate\Support\Facades\DB;
26	use Illuminate\Support\Str;
27	use Illuminate\Validation\Validator;
28	
29	/**
30	 * Seed `count` link blocks for the given professional in a capped category.
31	 * Mirrors the production schema enough to satisfy the cap query
32	 * (`whereIn('settings->category', $cappedCategories)`).
33	 */
34	function seedCappedLinks(string $professionalId, string $siteId, int $count, string $category = 'social'): void
35	{
36	    $now = now()->toDateTimeString();
37	    for ($i = 0; $i < $count; $i++) {
38	        DB::connection('pgsql')->table('site.blocks')->insert([
39	            'id' => (string) Str::uuid(),
40	            'professional_id' => $professionalId,
41	            'site_id' => $siteId,
42	            'block_group' => 'links',
43	            'block_type' => 'link',
44	            'settings' => json_encode(['category' => $category, 'platform' => 'instagram', 'handle' => "h{$i}"]),
45	            'sort_order' => $i,
46	            'is_active' => 1,
47	            'is_enabled' => 1,
48	            'created_at' => $now,
49	            'updated_at' => $now,
