3	namespace App\Http\Requests\Api\Professional\Site;
4	
5	use App\Http\Requests\BaseFormRequest;
6	use Illuminate\Validation\Rule;
7	
8	/**
9	 * Validates partial link block updates. Mirrors StoreLinkBlockRequest's two-mode
10	 * contract (social vs custom) but every field is `sometimes` — clients only need
11	 * to send what they're changing.
12	 *
13	 * Mode detection on update:
14	 *   - If `platform` is sent (non-null/empty), social mode: re-normalize via
15	 *     SocialLinkNormalizer using the new handle/url.
16	 *   - If `platform` is NOT sent, the existing block's mode is preserved by
17	 *     the controller — fields fall through to the existing values.
18	 *
19	 * Same security guarantees as StoreLinkBlockRequest: title sanitization,
20	 * scheme allowlist for custom URLs, normalizer-driven validation for socials.
21	 *
22	 * See docs/social-links.md.
23	 */
24	class UpdateLinkBlockRequest extends BaseFormRequest
25	{
26	    protected function prepareForValidation(): void
27	    {
28	        // `SubstituteBindings` middleware runs before this FormRequest is
29	        // resolved, so `route('linkBlock')` may already be the bound Block
30	        // model — not the raw UUID string. Normalise both shapes to the
31	        // underlying key so the `uuid` rule gets a plain string.
32	        $param = $this->route('linkBlock') ?? $this->route('block');
33	        $routeId = is_object($param) && method_exists($param, 'getKey')
34	            ? (string) $param->getKey()
35	            : $param;
36	
37	        $url = $this->input('url');
38	        $iconKey = $this->input('icon_key');
39	        $platform = $this->input('platform');
40	        $handle = $this->input('handle');
41	
42	        // Same defense-in-depth title sanitization as the Store request
43	        $this->cleanText(['title']);
44	
45	        $this->merge([
46	            'id' => $routeId,
47	            'url' => is_string($url) ? trim($url) : $url,
48	            'icon_key' => is_string($iconKey) ? trim($iconKey) : $iconKey,
49	            'platform' => is_string($platform) ? trim($platform) : $platform,
50	            'handle' => is_string($handle) ? trim($handle) : $handle,
51	        ]);
52	
53	        if (is_array($this->settings ?? null)) {
54	            $this->merge([
55	                'settings' => array_merge($this->settings, [
56	                    'note' => is_string($this->settings['note'] ?? null)
57	                        ? trim($this->settings['note'])
58	                        : ($this->settings['note'] ?? null),
59	                ]),
60	            ]);
61	        }
62	    }
63	
64	    public function rules(): array
65	    {
66	        return [
67	            'id' => ['required', 'uuid'],
68	
69	            // Social mode fields
70	            'platform' => ['sometimes', 'nullable', 'string', Rule::in(array_keys(config('sidest.social_platforms', [])))],
71	            'handle' => ['sometimes', 'nullable', 'string', 'max:100'],
72	
73	            // Custom / shared fields — all optional on update
74	            'title' => ['sometimes', 'nullable', 'string', 'max:80'],
75	            'url' => ['sometimes', 'nullable', 'string', 'max:2048'],
76	            'icon_key' => ['sometimes', 'nullable', 'string', Rule::in(config('sidest.link_block_icon_keys', []))],
77	
78	            'is_active' => ['sometimes', 'boolean'],
79	            'settings' => ['sometimes', 'array'],
80	            'settings.highlight' => ['sometimes', 'boolean'],
81	            'settings.note' => ['sometimes', 'string', 'max:140'],
82	            // Defense-in-depth: see StoreLinkBlockRequest for rationale. Enum-validate
83	            // settings.category so a client sending {category, settings: {category: 'bogus'}}
84	            // cannot bypass the top-level enum check through the update-path settings merge.
85	            'settings.category' => ['sometimes', 'nullable', 'string', Rule::in(config('sidest.link_categories', []))],
86	            'settings.live_check_enabled' => ['sometimes', 'boolean'],
87	
88	            // Category enum — all-optional on update (partial updates allowed).
89	            // Enum is still checked when present; controller applies override semantics.
90	            'category' => ['sometimes', 'nullable', 'string', Rule::in(config('sidest.link_categories', []))],
91	        ];
92	    }
93	
94	    public function withValidator($validator): void
95	    {
96	        $validator->after(function ($validator) {
97	            $platform = $this->input('platform');
98	            $handle = $this->input('handle');
99	            $url = $this->input('url');
100	
101	            // Social mode: if platform is being set, must have handle or url
102	            if ($platform !== null && $platform !== '') {
103	                if (($handle === null || $handle === '') && ($url === null || $url === '')) {
104	                    $validator->errors()->add('handle', 'Provide either a handle or a URL for this platform.');
105	                }
106	            } else {
107	                // Custom mode (or partial update): if a URL is being set, enforce scheme allowlist.
108	                // Don't require title/url here — partial updates are allowed.
109	                if ($url !== null && $url !== '' && ! $this->isAllowedScheme($url)) {
110	                    $validator->errors()->add('url', 'Custom link URLs must use http or https.');
111	                }
112	            }
113	
114	            // Settings allowlist (existing behaviour)
115	            $settings = $this->input('settings');
116	            if (is_array($settings)) {
117	                $allowed = config('sidest.link_block_settings_keys', []);
118	                $extra = array_diff(array_keys($settings), $allowed);
119	                if (! empty($extra)) {
120	                    $validator->errors()->add(
121	                        'settings',
122	                        'The settings field contains unsupported keys: '.implode(', ', $extra)
123	                    );
124	                }
125	            }
126	
127	            // Per-site cap on live_check_enabled blocks — prevents one user from
128	            // monopolizing the streaming poll budget.
129	            if (is_array($settings) && array_key_exists('live_check_enabled', $settings) && (bool) $settings['live_check_enabled']) {
130	                $currentBlock = $this->route('linkBlock') ?? $this->route('block');
131	                $siteId = is_object($currentBlock) ? ($currentBlock->site_id ?? null) : null;
132	                $currentBlockId = is_object($currentBlock) && method_exists($currentBlock, 'getKey')
133	                    ? (string) $currentBlock->getKey()
134	                    : null;
135	
136	                if ($siteId) {
137	                    $cap = (int) config('sidest.streaming.max_live_check_per_site', 5);
138	                    $existing = \App\Models\Core\Site\Block::query()
139	                        ->where('site_id', $siteId)
140	                        ->where('block_group', 'links')
141	                        ->when($currentBlockId, fn ($q) => $q->where('id', '!=', $currentBlockId))
142	                        ->whereRaw("settings->>'live_check_enabled' = 'true'")
143	                        ->count();
144	
145	                    if ($existing >= $cap) {
146	                        $validator->errors()->add(
147	                            'settings.live_check_enabled',
148	                            "You can enable live status checking on at most {$cap} link blocks per site."
149	                        );
150	                    }
151	                }
152	            }
153	        });
154	    }
155	
156	    /**
157	     * Reject schemes other than http/https. Same rationale as StoreLinkBlockRequest.
158	     */
159	    private function isAllowedScheme(string $url): bool
160	    {
161	        $scheme = parse_url($url, PHP_URL_SCHEME);
162	
163	        return is_string($scheme) && in_array(strtolower($scheme), ['http', 'https'], true);
164	    }
165	}
