19	/**
20	 * V2: CRUD + reorder for link blocks on the professional's mini-site.
21	 *
22	 * Supports two write modes (see docs/social-links.md):
23	 *   - **Social mode**: client sends `platform` + (`handle` OR `url`). The
24	 *     SocialLinkNormalizer validates and rebuilds a canonical https URL; the
25	 *     controller stores `settings.platform` and `settings.handle` as soft tags.
26	 *   - **Custom mode**: client sends `title` + `url` (legacy contract preserved).
27	 *     No platform binding, free-form icon_key.
28	 *
29	 * Authorization: every CRUD action checks `block->professional_id === current pro`.
30	 * This is the TOCTOU defense — must not be removed during refactors.
31	 */
32	class ProfessionalLinkBlockController extends ApiController
33	{
34	    use ResolveCurrentProfessional;
35	    use ResolveCurrentSite;
36	
37	    public function __construct(
38	        private readonly SocialLinkNormalizer $normalizer
39	    ) {}
40	
41	    private function authorizeCustomLinks(Professional $pro): void
42	    {
43	        $type = mb_strtolower(trim((string) ($pro->professional_type ?? '')));
44	        abort_unless(
45	            (bool) config("sidest.account_type_defaults.{$type}.custom_links_allowed", false),
46	            403,
47	            'Custom links are not available on your account type.'
48	        );
49	    }
50	
51	    public function index(IndexLinkBlockRequest $request)
52	    {
53	        $pro = $this->currentProfessional($request);
54	
55	        return $this->success([
56	            'blocks' => $pro->linkBlocks()->orderBy('sort_order')->get(),
57	        ]);
58	    }
59	
60	    public function store(StoreLinkBlockRequest $request)
61	    {
62	        $pro = $this->currentProfessional($request);
63	        $this->authorizeCustomLinks($pro);
64	        $site = $this->currentSite($pro);
65	
66	        $data = $request->validated();
67	
68	        // Social vs custom mode discriminator. Social mode delegates to the
69	        // normalizer to rebuild a canonical URL and tag settings.platform/handle.
70	        // Custom mode preserves the legacy field-by-field contract.
71	        try {
72	            $blockFields = $this->buildBlockFields($data);
73	        } catch (InvalidArgumentException $e) {
74	            return $this->error($e->getMessage(), 422);
75	        }
76	
77	        $linkBlock = DB::transaction(function () use ($pro, $site, $blockFields, $data) {
78	            DB::select('select pg_advisory_xact_lock(hashtext(?))', ["blocks-links:{$site->id}"]);
79	
80	            $maxSort = Block::query()
81	                ->where('site_id', $site->id)
82	                ->where('block_group', 'links')
83	                ->max('sort_order');
84	
85	            $maxSort = is_null($maxSort) ? -1 : (int) $maxSort;
86	
87	            $linkBlock = new Block(array_merge($blockFields, [
88	                'block_group' => 'links',
89	                'block_type' => 'link',
90	                'sort_order' => $maxSort + 1,
91	                'is_active' => $data['is_active'] ?? true,
92	            ]));
93	
94	            $linkBlock->professional_id = $pro->id;
95	            $linkBlock->site_id = $site->id;
96	            $linkBlock->save();
97	
98	            return $linkBlock->fresh();
99	        });
100	
101	        return $this->success(['block' => $linkBlock], 201);
102	    }
103	
104	    public function update(UpdateLinkBlockRequest $request, Block $linkBlock)
105	    {
106	        $pro = $this->currentProfessional($request);
107	        $this->authorizeCustomLinks($pro);
108	
109	        // TOCTOU defense: never trust route model binding alone. Verify the
110	        // block belongs to the current professional and is the right type.
111	        // Removing this check would let any authenticated user PATCH any
112	        // link block by guessing the UUID.
113	        abort_unless(
114	            $linkBlock->professional_id === $pro->id &&
115	            $linkBlock->block_group === 'links' &&
116	            $linkBlock->block_type === 'link',
117	            404
118	        );
119	
120	        $data = $request->validated();
121	        unset($data['id']);
122	
123	        // If the request switches into social mode (or stays in social mode with
124	        // a new handle/url), re-normalize. Otherwise fall through to the legacy
125	        // partial-update path that just fills whatever fields were sent.
126	        if (! empty($data['platform'])) {
127	            try {
128	                $normalized = $this->buildBlockFields($data);
129	            } catch (InvalidArgumentException $e) {
130	                return $this->error($e->getMessage(), 422);
131	            }
132	
133	            // Merge normalized social fields, preserving any other fields the
134	            // user happened to send (e.g. is_active toggle alongside).
135	            $linkBlock->fill(array_merge(
136	                array_intersect_key($data, array_flip(['is_active'])),
137	                $normalized
138	            ));
139	        } else {
140	            // Strip the social-mode-only keys before fill — they're not Block columns.
141	            unset($data['platform'], $data['handle']);
142	
143	            // Category lives in settings JSONB, not as a column. If the client
144	            // supplied a new category in isolation, merge it into existing settings.
145	            if (array_key_exists('category', $data)) {
146	                $existingSettings = is_array($linkBlock->settings) ? $linkBlock->settings : [];
147	                $existingSettings['category'] = $data['category'];
148	                $data['settings'] = array_merge($existingSettings, $data['settings'] ?? []);
149	                unset($data['category']);
150	            }
151	
152	            $linkBlock->fill($data);
153	        }
154	
155	        $linkBlock->save();
156	
157	        return $this->success(['block' => $linkBlock->fresh()]);
158	    }
159	
160	    /**
161	     * Translate a validated request payload into the Block column values to
162	     * persist. Handles the social/custom mode split centrally so store() and
163	     * update() share one source of truth.
164	     *
165	     * Social mode produces:
166	     *   - url       = canonical https URL from the normalizer
167	     *   - icon_key  = registry's icon_key for the platform
168	     *   - title     = user-supplied OR the platform's display_name
169	     *   - settings  = user settings + {platform, handle, category} soft tags
170	     *
171	     * Custom mode produces:
172	     *   - url       = as supplied
173	     *   - icon_key  = as supplied
174	     *   - title     = as supplied
175	     *   - settings  = user settings + {category} (required in request)
176	     *
177	     * Category resolution order:
178	     *   1. Request-provided `category` wins (validated against the enum in the Form Request).
179	     *   2. Else fall back to the platform's default_category (platform-link case).
180	     *   3. Else a 422-level guard (validation layer should have caught a missing category on custom links).
181	     *
182	     * @param  array<string, mixed>  $data  Validated request payload
183	     * @return array<string, mixed> Block fillable fields
184	     *
185	     * @throws InvalidArgumentException When social-mode normalization fails (caller maps to 422)
186	     */
187	    private function buildBlockFields(array $data): array
188	    {
189	        $platform = $data['platform'] ?? null;
190	        $requestedCategory = $data['category'] ?? null;
191	
192	        if ($platform !== null && $platform !== '') {
193	            $normalized = $this->normalizer->normalize(
194	                $platform,
195	                $data['handle'] ?? null,
196	                $data['url'] ?? null
197	            );
198	
199	            // Tag settings.platform + settings.handle so the frontend can
200	            // re-render the edit form in social mode and so analytics can
201	            // group by platform later (slow but works without a column).
202	            $settings = is_array($data['settings'] ?? null) ? $data['settings'] : [];
203	            $settings['platform'] = $normalized['platform_key'];
204	            if ($normalized['handle'] !== null) {
205	                $settings['handle'] = $normalized['handle'];
206	            }
207	
208	            // Category: explicit override wins, else platform default.
209	            $registry = config("sidest.social_platforms.{$normalized['platform_key']}", []);
210	            $settings['category'] = $requestedCategory ?: ($registry['default_category'] ?? 'other');
211	
212	            return [
213	                'title' => ($data['title'] ?? '') !== '' ? $data['title'] : $normalized['display_name'],
214	                'url' => $normalized['url'],
215	                'icon_key' => $normalized['icon_key'],
216	                'settings' => $settings,
217	            ];
218	        }
219	
220	        // Custom mode: category is required by the Form Request. Defensive
221	        // default here in case a future code path calls buildBlockFields
222	        // directly with incomplete data.
223	        $settings = is_array($data['settings'] ?? null) ? $data['settings'] : [];
224	        if ($requestedCategory === null || $requestedCategory === '') {
225	            throw new InvalidArgumentException('A category is required for custom links.');
226	        }
227	        $settings['category'] = $requestedCategory;
228	
229	        return [
230	            'title' => $data['title'] ?? null,
231	            'url' => $data['url'] ?? null,
232	            'icon_key' => $data['icon_key'] ?? null,
233	            'settings' => $settings,
234	        ];
235	    }
