237	    public function destroy(DestroyLinkBlockRequest $request, Block $linkBlock)
238	    {
239	        $request->validated();
240	
241	        $pro = $this->currentProfessional($request);
242	
243	        abort_unless(
244	            $linkBlock->professional_id === $pro->id &&
245	            $linkBlock->block_group === 'links' &&
246	            $linkBlock->block_type === 'link',
247	            404
248	        );
249	
250	        $linkBlock->delete();
251	
252	        return $this->success(['deleted' => true]);
253	    }
