255	    public function reorder(ReorderBlocksRequest $request)
256	    {
257	        $pro = $this->currentProfessional($request);
258	        $this->authorizeCustomLinks($pro);
259	        $site = $this->currentSite($pro);
260	
261	        $ids = array_values(array_unique($request->validated()['ids'] ?? []));
262	
263	        DB::transaction(function () use ($pro, $site, $ids) {
264	            DB::select('select pg_advisory_xact_lock(hashtext(?))', ["blocks-links:{$site->id}"]);
265	
266	            $allIds = Block::query()
267	                ->where('professional_id', $pro->id)
268	                ->where('site_id', $site->id)
269	                ->where('block_group', 'links')
270	                ->where('block_type', 'link')
271	                ->lockForUpdate()
272	                ->orderBy('sort_order')
273	                ->orderBy('created_at')
274	                ->pluck('id')
275	                ->all();
276	
277	            $allSet = array_flip($allIds);
278	
279	            foreach ($ids as $id) {
280	                if (! isset($allSet[$id])) {
281	                    abort(422, 'One or more blocks are invalid');
282	                }
283	            }
284	
285	            $remaining = array_values(array_diff($allIds, $ids));
286	            $newOrder = array_merge($ids, $remaining);
287	            $offset = (int) Block::query()
288	                ->where('professional_id', $pro->id)
289	                ->where('site_id', $site->id)
290	                ->where('block_group', 'links')
291	                ->max('sort_order') + 1000;
292	
293	            foreach ($newOrder as $i => $id) {
294	                Block::query()
295	                    ->where('professional_id', $pro->id)
296	                    ->where('site_id', $site->id)
297	                    ->where('block_group', 'links')
298	                    ->where('block_type', 'link')
299	                    ->where('id', $id)
300	                    ->update(['sort_order' => $offset + $i]);
301	            }
302	
