4	
5	use App\Models\Core\Site\Block;
6	use App\Services\Site\SocialLinkNormalizer;
7	use Illuminate\Console\Command;
8	use Illuminate\Support\Facades\DB;
9	use Illuminate\Support\Facades\Log;
10	use InvalidArgumentException;
11	
12	/**
13	 * One-shot backfill: tag ALL link blocks with `settings.platform`,
14	 * `settings.handle` (when extractable), and `settings.category`.
15	 *
16	 * Idempotent — safe to re-run. Skips rows that already have both platform
17	 * and category set. Rows with a known social icon_key get full platform
18	 * resolution; custom/unknown rows get category='other' only.
19	 *
20	 * Why we have this:
21	 *   When the social_platforms registry was introduced, existing link blocks
22	 *   used icon_key='instagram' etc. but had no platform tag in settings. The
23	 *   category field was added later, requiring another pass over all link
24	 *   blocks (including custom ones with no platform).
25	 *
26	 * Run order:
27	 *   1. Always run with --dry-run first to preview the stats.
28	 *   2. Run for real once you've reviewed.
29	 *   3. Optional: --limit=N for a cautious first batch on large datasets.
30	 *
31	 * Security:
32	 *   - Per-chunk DB transaction so a partial chunk failure rolls back cleanly.
33	 *   - chunkById(200) keeps memory bounded.
34	 *   - Logging hygiene: warnings reference block ID + platform key only,
35	 *     never the full URL or handle.
36	 *   - Audit log line at start records the operator and run mode.
37	 *
38	 * See docs/social-links.md.
39	 */
40	class BackfillSocialLinksCommand extends Command
41	{
42	    protected $signature = 'sidest:backfill-social-links
43	        {--dry-run : Show what would change without writing}
44	        {--limit=0 : Process at most N rows (0 = unlimited)}';
45	
46	    protected $description = 'Backfill link blocks with settings.platform, settings.handle (when derivable), and settings.category. Idempotent — safe to re-run.';
47	
48	    public function handle(SocialLinkNormalizer $normalizer): int
49	    {
50	        $registry = config('sidest.social_platforms', []);
51	        $iconToPlatform = $this->buildIconToPlatformMap($registry);
52	
53	        $dryRun = (bool) $this->option('dry-run');
54	        $limit = (int) $this->option('limit');
55	
56	        Log::info('Backfill link blocks started', [
57	            'operator' => get_current_user() ?: 'unknown',
58	            'dry_run' => $dryRun,
59	            'limit' => $limit,
60	        ]);
61	
62	        $stats = [
63	            'total' => 0,
64	            'already_tagged' => 0,
65	            'tagged_with_handle' => 0,
66	            'tagged_url_only' => 0,
67	            'category_only' => 0,
68	            'url_normalized' => 0,
69	            'unmatched_host' => 0,
70	            'errors' => 0,
71	        ];
72	
73	        // Process ALL link blocks. Social-icon rows get platform + category
74	        // resolution; other rows get category='other'. See the plan §Task 16
75	        // and docs/social-links.md for the rationale.
76	        $query = Block::query()
77	            ->where('block_group', 'links')
78	            ->where('block_type', 'link')
79	            ->orderBy('id');
80	
81	        if ($limit > 0) {
82	            $query->limit($limit);
83	        }
84	
85	        $query->chunkById(200, function ($blocks) use (&$stats, $iconToPlatform, $registry, $normalizer, $dryRun) {
86	            DB::transaction(function () use ($blocks, &$stats, $iconToPlatform, $registry, $normalizer, $dryRun) {
87	                foreach ($blocks as $block) {
88	                    $stats['total']++;
89	
90	                    $settings = is_array($block->settings) ? $block->settings : [];
91	                    $hasCategory = isset($settings['category']);
92	                    $hasPlatform = isset($settings['platform']);
93	
94	                    // Fully-tagged rows: skip (idempotent).
95	                    if ($hasCategory && $hasPlatform) {
96	                        $stats['already_tagged']++;
97	
98	                        continue;
99	                    }
100	
101	                    // Identify the platform to use for category lookup + (if the
102	                    // row isn't platform-tagged yet) URL normalization.
103	                    $platformKey = $hasPlatform
104	                        ? $settings['platform']
105	                        : ($iconToPlatform[$block->icon_key] ?? null);
106	
107	                    // Legacy social-icon path: row has a social icon_key but no
108	                    // settings.platform yet. Normalize URL, tag platform/handle.
109	                    if (! $hasPlatform && $platformKey !== null && $block->url !== null) {
110	                        try {
111	                            $normalized = $normalizer->normalize($platformKey, null, $block->url);
112	                        } catch (InvalidArgumentException $e) {
113	                            // URL doesn't match the platform's host_allowlist
114	                            // (e.g. a Linktree URL behind an Instagram icon).
115	                            // Leave platform/handle alone but still backfill
116	                            // category so the row isn't stuck.
117	                            $stats['unmatched_host']++;
118	                            $this->warn(sprintf('  Host mismatch for block %s (%s) — category-only backfill', $block->id, $platformKey));
119	                            Log::warning('Backfill: host mismatch', [
120	                                'block_id' => (string) $block->id,
121	                                'platform' => $platformKey,
122	                            ]);
123	                            $platformKey = null; // fall through to category=other
124	                        }
125	
126	                        if ($platformKey !== null && isset($normalized)) {
127	                            $settings['platform'] = $platformKey;
128	                            if ($normalized['handle'] !== null) {
129	                                $settings['handle'] = $normalized['handle'];
130	                                $stats['tagged_with_handle']++;
131	                            } else {
132	                                $stats['tagged_url_only']++;
133	                            }
134	
135	                            if ($normalized['url'] !== $block->url) {
136	                                $stats['url_normalized']++;
137	                                if (! $dryRun) {
138	                                    $block->url = $normalized['url'];
139	                                }
140	                            }
141	                        }
142	                    }
143	
144	                    // Resolve category: platform default, or 'other' for
145	                    // custom/unknown rows and host-mismatch fallbacks.
146	                    if (! $hasCategory) {
147	                        $settings['category'] = $platformKey !== null
148	                            ? ($registry[$platformKey]['default_category'] ?? 'other')
149	                            : 'other';
150	                        $stats['category_only']++;
151	                    }
152	
153	                    if (! $dryRun) {
154	                        $block->settings = $settings;
155	                        $block->save();
156	                    }
157	
158	                    unset($normalized);
159	                }
160	            });
161	        });
162	
163	        $this->newLine();
164	        $this->info($dryRun ? 'DRY RUN — no changes written.' : 'Backfill complete.');
165	        $this->table(
166	            ['Metric', 'Count'],
167	            collect($stats)->map(fn ($v, $k) => [$k, $v])->all()
168	        );
169	
170	        return self::SUCCESS;
171	    }
172	
173	    /**
174	     * Build a reverse map of icon_key → platform_key from the registry, so we
175	     * can look up "which platform does this existing block's icon belong to?"
176	     * in O(1) per row.
177	     *
178	     * @param  array<string, array<string, mixed>>  $registry
179	     * @return array<string, string>
180	     */
181	    private function buildIconToPlatformMap(array $registry): array
182	    {
183	        $map = [];
184	        foreach ($registry as $platformKey => $config) {
185	            $map[$config['icon_key']] = $platformKey;
186	        }
187	
188	        return $map;
189	    }
190	}
