3	namespace App\Http\Requests\Api\Professional\Site;
4	
5	use App\Http\Requests\BaseFormRequest;
6	use Illuminate\Support\Facades\DB;
7	use Illuminate\Validation\Rule;
8	
9	/**
10	 * Validates new link block creation. Supports two write modes:
11	 *
12	 *   1. **Social mode** — `platform` is set (must be a key in
13	 *      config('sidest.social_platforms')). Either `handle` OR `url` must be
14	 *      provided. The controller delegates to SocialLinkNormalizer to validate,
15	 *      strip a leading '@', and rebuild a canonical https URL.
16	 *
17	 *   2. **Custom mode** — no `platform`. Behaves like the legacy contract:
18	 *      `title` AND `url` are both required. `icon_key` is optional.
19	 *
20	 * Security:
21	 *   - Custom-mode URLs are restricted to http/https schemes only — no
22	 *     javascript:, data:, file:, ftp:. Caught in withValidator() below.
23	 *   - `title` is sanitized in prepareForValidation(): control chars stripped,
24	 *     HTML tags removed via strip_tags() as defense-in-depth on top of frontend
25	 *     escaping.
26	 *   - Social-mode handle/url validation is delegated to the normalizer service
27	 *     which enforces ASCII-only handles (homoglyph protection) and host
28	 *     allowlists (phishing protection).
29	 *
30	 * See docs/social-links.md for the full contract.
31	 */
32	class StoreLinkBlockRequest extends BaseFormRequest
33	{
34	    protected function prepareForValidation(): void
35	    {
36	        $url = $this->input('url');
37	        $iconKey = $this->input('icon_key');
38	        $platform = $this->input('platform');
39	        $handle = $this->input('handle');
40	
41	        $this->cleanText(['title']);
42	
43	        $this->merge([
44	            'url' => is_string($url) ? trim($url) : $url,
45	            'icon_key' => is_string($iconKey) ? trim($iconKey) : $iconKey,
46	            'platform' => is_string($platform) ? trim($platform) : $platform,
47	            'handle' => is_string($handle) ? trim($handle) : $handle,
48	        ]);
49	
50	        if (is_array($this->settings ?? null)) {
51	            $this->merge([
52	                'settings' => array_merge($this->settings, [
53	                    'note' => is_string($this->settings['note'] ?? null)
54	                        ? trim($this->settings['note'])
55	                        : ($this->settings['note'] ?? null),
56	                ]),
57	            ]);
58	        }
59	    }
60	
61	    public function rules(): array
62	    {
63	        return [
64	            // Social mode fields. `url` is validated lazily as a string here
65	            // because the normalizer runs its own host-allowlist check; using
66	            // Laravel's `url` rule would reject deep links we want to accept.
67	            'platform' => ['sometimes', 'nullable', 'string', Rule::in(array_keys(config('sidest.social_platforms', [])))],
68	            'handle' => ['sometimes', 'nullable', 'string', 'max:100'],
69	
70	            // Custom mode fields (also reused for social mode auto-fallbacks)
71	            'title' => ['sometimes', 'nullable', 'string', 'max:80'],
72	            'url' => ['sometimes', 'nullable', 'string', 'max:2048'],
73	            'icon_key' => ['sometimes', 'nullable', 'string', Rule::in(config('sidest.link_block_icon_keys', []))],
74	
75	            'is_active' => ['sometimes', 'boolean'],
76	            'settings' => ['sometimes', 'array'],
77	            'settings.highlight' => ['sometimes', 'boolean'],
78	            'settings.note' => ['sometimes', 'string', 'max:140'],
79	            // Defense-in-depth: even though the controller overwrites settings.category
80	            // with the top-level category before save, enum-validate the nested form
81	            // in case a code path ever merges settings without overwriting.
82	            'settings.category' => ['sometimes', 'nullable', 'string', Rule::in(config('sidest.link_categories', []))],
83	
84	            // Category enum — always validated against the registry when supplied.
85	            // Required for custom links (enforced in withValidator); optional for
86	            // social links (controller falls back to the platform's default_category).
87	            'category' => ['sometimes', 'nullable', 'string', Rule::in(config('sidest.link_categories', []))],
88	        ];
89	    }
90	
91	    public function withValidator($validator): void
92	    {
93	        $validator->after(function ($validator) {
94	            $platform = $this->input('platform');
95	            $handle = $this->input('handle');
96	            $url = $this->input('url');
97	            $title = $this->input('title');
98	
99	            // Social vs custom mode discriminator
100	            if ($platform !== null && $platform !== '') {
101	                // Social mode: must have handle OR url
102	                if (($handle === null || $handle === '') && ($url === null || $url === '')) {
103	                    $validator->errors()->add('handle', 'Provide either a handle or a URL for this platform.');
104	                }
105	            } else {
106	                // Custom mode: title AND url both required (legacy contract preserved)
107	                if ($title === null || $title === '') {
108	                    $validator->errors()->add('title', 'The title field is required for custom links.');
109	                }
110	                if ($url === null || $url === '') {
111	                    $validator->errors()->add('url', 'The url field is required for custom links.');
112	                } elseif (! $this->isAllowedScheme($url)) {
113	                    $validator->errors()->add('url', 'Custom link URLs must use http or https.');
114	                }
115	
116	                // Category is required for custom links; platform links fall back
117	                // to the registry's default_category when omitted.
118	                $category = $this->input('category');
119	                if ($category === null || $category === '') {
120	                    $validator->errors()->add('category', 'The category field is required for custom links.');
121	                }
122	            }
123	
124	            // Platform-link cap — defence-in-depth on top of the dashboard's
125	            // disabled-Add-button UX. Resolves the link's effective category
126	            // (top-level `category`, then platform default) and counts
127	            // existing rows in the platform-links scope. Refuses creation
128	            // beyond `config('sidest.platform_links_max')` so a savvy user
129	            // can't bypass the UI cap by hammering the API.
130	            $effectiveCategory = $this->input('category');
131	            if (($effectiveCategory === null || $effectiveCategory === '') && is_string($platform) && $platform !== '') {
132	                $effectiveCategory = config("sidest.social_platforms.{$platform}.default_category");
133	            }
134	
135	            $cappedCategories = (array) config('sidest.platform_links_categories', []);
136	            if (is_string($effectiveCategory) && in_array($effectiveCategory, $cappedCategories, true)) {
137	                $max = (int) config('sidest.platform_links_max', 7);
138	                // Resolve the professional whose cap we're enforcing. Auth::user()
139	                // is always null under Supabase JWT, so $this->user() can't be
140	                // used. Prefer the route-bound target (staff path:
141	                // /staff/.../professionals/{professional}/links) and fall back
142	                // to the auth-context professional placed on request attributes
143	                // by Context\LoadCurrentProfessional (self path).
144	                $pro = $this->route('professional') ?? $this->attributes->get('professional');
145	                $proId = $pro instanceof \App\Models\Core\Professional\Professional ? $pro->id : null;
146	                if ($proId !== null && $max > 0) {
147	                    $existing = \App\Models\Core\Site\Block::query()
148	                        ->where('professional_id', $proId)
149	                        ->where('block_group', 'links')
150	                        ->whereNull('deleted_at')
151	                        ->whereIn(DB::raw("settings->>'category'"), $cappedCategories)
152	                        ->count();
153	                    if ($existing >= $max) {
154	                        $validator->errors()->add(
155	                            'category',
156	                            "You've reached the limit of {$max} platform links. Remove one to add another."
157	                        );
158	                    }
159	                }
160	            }
161	
162	            // Settings allowlist (existing behaviour)
163	            $settings = $this->input('settings');
164	            if (is_array($settings)) {
165	                $allowed = config('sidest.link_block_settings_keys', []);
166	                $extra = array_diff(array_keys($settings), $allowed);
167	                if (! empty($extra)) {
168	                    $validator->errors()->add(
169	                        'settings',
170	                        'The settings field contains unsupported keys: '.implode(', ', $extra)
171	                    );
172	                }
173	            }
174	        });
175	    }
176	
177	    /**
178	     * Reject schemes other than http/https for custom links. Blocks
179	     * javascript:, data:, file:, ftp:, and similar XSS / exfiltration vectors.
180	     */
181	    private function isAllowedScheme(string $url): bool
182	    {
183	        $scheme = parse_url($url, PHP_URL_SCHEME);
184	
185	        return is_string($scheme) && in_array(strtolower($scheme), ['http', 'https'], true);
186	    }
187	}
