102	                    // row isn't platform-tagged yet) URL normalization.
103	                    $platformKey = $hasPlatform
104	                        ? $settings['platform']
105	                        : ($iconToPlatform[$block->icon_key] ?? null);
106	
107	                    // Legacy social-icon path: row has a social icon_key but no
108	                    // settings.platform yet. Normalize URL, tag platform/handle.
109	                    if (! $hasPlatform && $platformKey !== null && $block->url !== null) {
110	                        try {
111	                            $normalized = $normalizer->normalize($platformKey, null, $block->url);
112	                        } catch (InvalidArgumentException $e) {
113	                            // URL doesn't match the platform's host_allowlist
114	                            // (e.g. a Linktree URL behind an Instagram icon).
115	                            // Leave platform/handle alone but still backfill
116	                            // category so the row isn't stuck.
117	                            $stats['unmatched_host']++;
118	                            $this->warn(sprintf('  Host mismatch for block %s (%s) — category-only backfill', $block->id, $platformKey));
119	                            Log::warning('Backfill: host mismatch', [
120	                                'block_id' => (string) $block->id,
121	                                'platform' => $platformKey,
122	                            ]);
123	                            $platformKey = null; // fall through to category=other
124	                        }
125	
126	                        if ($platformKey !== null && isset($normalized)) {
127	                            $settings['platform'] = $platformKey;
128	                            if ($normalized['handle'] !== null) {
129	                                $settings['handle'] = $normalized['handle'];
130	                                $stats['tagged_with_handle']++;
131	                            } else {
132	                                $stats['tagged_url_only']++;
133	                            }
134	
135	                            if ($normalized['url'] !== $block->url) {
136	                                $stats['url_normalized']++;
137	                                if (! $dryRun) {
138	                                    $block->url = $normalized['url'];
139	                                }
140	                            }
141	                        }
142	                    }
143	
144	                    // Resolve category: platform default, or 'other' for
145	                    // custom/unknown rows and host-mismatch fallbacks.
146	                    if (! $hasCategory) {
147	                        $settings['category'] = $platformKey !== null
148	                            ? ($registry[$platformKey]['default_category'] ?? 'other')
149	                            : 'other';
150	                        $stats['category_only']++;
151	                    }
152	
153	                    if (! $dryRun) {
154	                        $block->settings = $settings;
155	                        $block->save();
156	                    }
157	
158	                    unset($normalized);
159	                }
160	            });
161	        });
162	
163	        $this->newLine();
164	        $this->info($dryRun ? 'DRY RUN — no changes written.' : 'Backfill complete.');
165	        $this->table(
166	            ['Metric', 'Count'],
167	            collect($stats)->map(fn ($v, $k) => [$k, $v])->all()
168	        );
169	
170	        return self::SUCCESS;
171	    }
172	
173	    /**
174	     * Build a reverse map of icon_key → platform_key from the registry, so we
175	     * can look up "which platform does this existing block's icon belong to?"
176	     * in O(1) per row.
177	     *
178	     * @param  array<string, array<string, mixed>>  $registry
179	     * @return array<string, string>
180	     */
181	    private function buildIconToPlatformMap(array $registry): array
182	    {
183	        $map = [];
184	        foreach ($registry as $platformKey => $config) {
185	            $map[$config['icon_key']] = $platformKey;
186	        }
187	
188	        return $map;
189	    }
190	}
